```js
async function fetchJson(path, params={}, attempts=3) {
  const url = new URL(path, API_BASE);
  Object.entries(params).forEach(([k,v])=>url.searchParams.set(k,v));
  let lastError;
  for (let attempt=0; attempt<attempts; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(()=>controller.abort(), 20000);
    try {
      const response = await fetch(url, {signal: controller.signal, headers: {"Accept":"application/json"}});
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return await response.json();
    } catch (error) { lastError = error; if (attempt<attempts-1) await sleep(500*2**attempt); }
    finally { clearTimeout(timer); }
  }
  throw new Error(lastError?.message || "request failed");
}
```
`new URL(path, API_BASE)` with API_BASE no trailing slash: `new URL("/api/v3/ping", "https://...")` works. Good.
