  if (!Number.isFinite(number)) return "—";
  const abs = Math.abs(number);
  const maximumFractionDigits = abs >= 1000 ? 2 : abs >= 1 ? 4 : abs >= 0.01 ? 5 : 8;
  return number.toLocaleString("en-US", {maximumFractionDigits, minimumFractionDigits: 0});
}
