input.content:
:root {
  --bg: #06090f;
  --bg-2: #080d15;
  --panel: rgba(12, 18, 29, 0.82);
  --panel-2: rgba(16, 24, 38, 0.9);
  --line: rgba(148, 163, 184, 0.13);
  --line-strong: rgba(148, 163, 184, 0.22);
  --text: #e9eff8;
  --muted: #8fa0b6;
  --muted-2: #65758b;
  --green: #38e0a0;
  --green-2: #14b981;
  --green-soft: rgba(56, 224, 160, 0.1);
  --blue: #6aa8ff;
  --blue-soft: rgba(106, 168, 255, 0.12);
  --amber: #f6c453;
  --amber-soft: rgba(246, 196, 83, 0.12);
  --red: #ff6b7a;
  --red-soft: rgba(255, 107, 122, 0.12);
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 30px 90px rgba(0, 0, 0, 0.45);
  --font: "Manrope", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  overflow-x: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

[hidden] {
  display: none !important;
}

button,
input {
  font: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

svg {
  display: block;
}

.svg-sprite {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
}

.icon {
  width: 1.1em;
  height: 1.1em;
  flex: none;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
