  background:
    radial-gradient(1100px 600px at 88% -12%, rgba(56, 224, 160, 0.08), transparent 60%),
    radial-gradient(900px 600px at -8% 18%, rgba(106, 168, 255, 0.07), transparent 62%),
    var(--bg);
}

.app-shell::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  background-image:
    linear-gradient(rgba(148, 163, 184, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(148, 163, 184, 0.04) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(ellipse at 50% 0%, black 10%, transparent 72%);
  opacity: 0.55;
}

.app-header {
  position: sticky;
  top: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px 32px;
  border-bottom: 1px solid var(--line);
  background: rgba(6, 9, 15, 0.78);
  backdrop-filter: blur(18px);
}

.app-header-left,
.app-header-right {
  display: flex;
  align-items: center;
  gap: 14px;
}

.private-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border: 1px solid rgba(56, 224, 160, 0.22);
  border-radius: 999px;
  background: var(--green-soft);
  color: var(--green);
  font-family: var(--mono);
  font-size: 0.58rem;
  letter-spacing: 0.12em;
}

.private-badge .icon {
  width: 12px;
  height: 12px;
}

.live-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
}

.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 0 4px var(--green-soft);
}

.live-status.scanning .live-dot {
  animation: pulse 1.1s infinite;
}

.live-status.error .live-dot {
  background: var(--red);
  box-shadow: 0 0 0 4px var(--red-soft);
}

.header-divider {
  width: 1px;
  height: 24px;
  background: var(--line);
}

.last-scan {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.last-scan span {
  color: var(--muted-2);
  font-size: 0.6rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.last-scan strong {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.7rem;
  font-weight: 500;
}

.app-main {
  position: relative;
  z-index: 1;
  max-width: 1320px;
  margin: 0 auto;
  padding: 40px 32px 60px;
}

.desk-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 40px;
  margin-bottom: 30px;
}

.desk-copy h1 {
  margin: 0;
  font-size: clamp(2.2rem, 4vw, 3.4rem);
  letter-spacing: -0.055em;
  line-height: 1;
}

.desk-copy .lede {
  margin-top: 16px;
}

.scan-clock {
  flex: none;
  min-width: 180px;
  padding: 16px 18px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--panel);
}

.scan-clock > span {
  display: block;
  color: var(--muted-2);
  font-size: 0.62rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.scan-clock strong {
  display: block;
  margin-top: 2px;
  color: var(--green);
  font-family: var(--mono);
  font-size: 1.55rem;
  font-weight: 500;
  letter-spacing: -0.04em;
}

.scan-progress {
  height: 3px;
  margin-top: 10px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(148, 163, 184, 0.12);
}

.scan-progress span {
  display: block;
  width: 0;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--green), var(--blue));
  transition: width 0.5s linear;
}

.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 26px;
}

.stat-card {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--panel);
  backdrop-filter: blur(10px);
}

.stat-icon {
  display: grid;
  flex: none;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.02);
  color: var(--muted);
}

.stat-icon.accent {
  border-color: rgba(56, 224, 160, 0.2);
  background: var(--green-soft);
  color: var(--green);
}

.stat-icon .icon {
  width: 17px;
  height: 17px;
}

.stat-card > div {
  min-width: 0;
}

.stat-card span:not(.stat-icon) {
  display: block;
  color: var(--muted);
  font-size: 0.68rem;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.stat-card strong {
  display: block;
  margin-top: 1px;
  font-size: 1.55rem;
  letter-spacing: -0.04em;
  line-height: 1.15;
}

.stat-card small {
  display: block;
  margin-top: 2px;
  color: var(--muted-2);
  font-size: 0.66rem;
}

.stat-card strong.regime-up {
  color: var(--green);
}

.stat-card strong.regime-down {
  color: var(--red);
}

.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(310px, 0.78fr);
  gap: 18px;
  align-items: start;
}

.signals-column {
  min-width: 0;
}

.section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 14px;
}

.section-head h2 {
  margin: 0;
  font-size: 1.35rem;
  letter-spacing: -0.03em;
}

.count-pill {
  display: inline-grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  margin-left: 4px;
  padding: 0 7px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.68rem;
  vertical-align: 2px;
}

.section-meta {
  color: var(--muted-2);
  font-size: 0.7rem;
  text-align: right;
}

.scan-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel);
  color: var(--muted);
  font-size: 0.78rem;
}

.scan-banner.error {
  border-color: rgba(255, 107, 122, 0.3);
  background: var(--red-soft);
  color: #ffc2c8;
}

.scan-banner.warning {
  border-color: rgba(246, 196, 83, 0.3);
  background: var(--amber-soft);
  color: #ffe0a3;
}

.signal-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.signal-card {
  position: relative;
  padding: 22px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(180deg, rgba(17, 25, 40, 0.9), rgba(10, 15, 24, 0.92));
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.22);
  animation: fadeUp 0.5s both;
  animation-delay: var(--delay, 0ms);
}

.signal-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 3px;
  background: linear-gradient(180deg, var(--green), transparent 80%);
}

.signal-card.short::before {
  background: linear-gradient(180deg, var(--red), transparent 80%);
}

.signal-card::after {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(56, 224, 160, 0.4), transparent);
}

.signal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.symbol-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
}

.symbol-line h3 {
  margin: 0;
  font-size: 1.45rem;
  letter-spacing: -0.035em;
}

.side-pill {
  padding: 3px 8px;
  border-radius: 6px;
  font-family: var(--mono);
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.side-pill.long {
  border: 1px solid rgba(56, 224, 160, 0.22);
  background: var(--green-soft);
  color: var(--green);
}

.side-pill.short {
  border: 1px solid rgba(255, 107, 122, 0.22);
  background: var(--red-soft);
  color: var(--red);
}

.new-badge {
  padding: 3px 7px;
  border: 1px solid rgba(106, 168, 255, 0.25);
  border-radius: 6px;
  background: var(--blue-soft);
  color: var(--blue);
  font-family: var(--mono);
  font-size: 0.56rem;
  letter-spacing: 0.1em;
}

.setup {
  margin: 3px 0 0;
  color: var(--muted);
  font-size: 0.86rem;
}

.score-ring {
  position: relative;
  flex: none;
  width: 66px;
  height: 66px;
}

.score-ring svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.score-ring circle {
  fill: none;
  stroke-width: 4;
}

.ring-track {
  stroke: rgba(148, 163, 184, 0.14);
}

.ring-value {
  stroke: var(--green);
  stroke-linecap: round;
  filter: drop-shadow(0 0 6px rgba(56, 224, 160, 0.35));
  transition: stroke-dashoffset 0.8s ease;
}

.score-text {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 1px;
  padding-top: 22px;
}

.score-text strong {
  font-size: 1.15rem;
  letter-spacing: -0.04em;
}

.score-text span {
  color: var(--muted-2);
  font-size: 0.55rem;
}

.levels-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-top: 18px;
}

.level {
  padding: 10px 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(4, 8, 14, 0.45);
}

.level span {
  display: block;
  color: var(--muted-2);
  font-size: 0.6rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.level strong {
  display: block;
  margin-top: 2px;
  font-family: var(--mono);
  font-size: 0.8rem;
  font-weight: 500;
}

.level.entry strong {
  color: var(--green);
}

.level.stop strong {
  color: var(--red);
}

.level.tp strong {
  color: var(--blue);
}

.metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-top: 8px;
}

.metrics-grid > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 10px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.02);
}

.metrics-grid span {
  color: var(--muted-2);
  font-size: 0.62rem;
}

.metrics-grid strong {
  font-family: var(--mono);
  font-size: 0.7rem;
  font-weight: 500;
}

.signal-body {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(150px, 0.6fr);
  gap: 20px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
}

.mini-label {
  display: block;
  margin-bottom: 8px;
  color: var(--muted-2);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.reasons ul {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.reasons li {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  color: var(--muted);
  font-size: 0.75rem;
  line-height: 1.4;
}

.reasons .icon {
  width: 13px;
  height: 13px;
  margin-top: 2px;
  color: var(--green);
}

.structure-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 0;
  border-bottom: 1px dashed rgba(148, 163, 184, 0.1);
}

.structure-row:last-child {
  border-bottom: 0;
}

.structure-row span {
  color: var(--muted-2);
  font-size: 0.66rem;
}

.structure-row strong {
  font-family: var(--mono);
  font-size: 0.7rem;
  font-weight: 500;
}

.signal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 16px;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.signal-time {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted-2);
  font-size: 0.66rem;
}

.signal-time .icon {
  width: 13px;
  height: 13px;
}

.copy-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  font-size: 0.68rem;
  font-weight: 650;
  transition: color 0.18s ease, border-color 0.18s ease, background 0.18s ease;
}

.copy-btn:hover {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
}

.copy-btn.copied {
  border-color: rgba(56, 224, 160, 0.3);
  background: var(--green-soft);
  color: var(--green);
}

.copy-btn .icon {
  width: 13px;
  height: 13px;
}

/* ---------- Empty / loading ---------- */

.empty-state {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 54px 28px 46px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(56, 224, 160, 0.07), transparent 60%),
    var(--panel);
  text-align: center;
}

.empty-state h3 {
  margin: 14px 0 6px;
  font-size: 1.5rem;
  letter-spacing: -0.03em;
}

.empty-state p {
  max-width: 440px;
  margin: 0;
  color: var(--muted);
  font-size: 0.84rem;
}

.empty-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 20px;
}

.empty-actions span {
  color: var(--muted-2);
  font-size: 0.68rem;
}

.radar {
  position: relative;
  display: grid;
  place-items: center;
  width: 90px;
  height: 90px;
  margin-bottom: 4px;
}

.radar span {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(56, 224, 160, 0.2);
  border-radius: 50%;
  animation: radar 3s infinite;
}

.radar span:nth-child(2) {
  inset: 14px;
  animation-delay: 0.6s;
}

.radar span:nth-child(3) {
  inset: 28px;
  animation-delay: 1.2s;
}

.radar-core {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 18px rgba(56, 224, 160, 0.9);
}

.signal-card.skeleton {
  min-height: 300px;
  pointer-events: none;
}

.sk-line,
.sk-block {
  border-radius: 6px;
  background: linear-gradient(
    90deg,
    rgba(148, 163, 184, 0.07) 25%,
    rgba(148, 163, 184, 0.15) 37%,
    rgba(148, 163, 184, 0.07) 63%
  );
  background-size: 400% 100%;
  animation: shimmer 1.4s infinite;
}

.sk-line {
  height: 11px;
  margin-bottom: 10px;
}

.sk-block {
  height: 56px;
  margin-top: 16px;
}

.sk-row {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-top: 18px;
}

.sk-row .sk-block {
  height: 48px;
  margin: 0;
}

.w-30 { width: 30%; }
.w-40 { width: 40%; }
.w-55 { width: 55%; }
.w-70 { width: 70%; }

/* ---------- Panels ---------- */

.panel {
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--panel);
  backdrop-filter: blur(10px);
}

.panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.panel-head h3 {
  margin: 0;
  font-size: 1rem;
  letter-spacing: -0.02em;
}

.panel-head .eyebrow {
  margin-bottom: 5px;
}

.panel-icon {
  width: 16px;
  height: 16px;
  color: var(--muted-2);
}

.status-chip {
  padding: 4px 8px;
  border: 1px solid rgba(56, 224, 160, 0.2);
  border-radius: 6px;
  background: var(--green-soft);
  color: var(--green);
  font-family: var(--mono);
  font-size: 0.58rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.status-chip.scanning {
  border-color: rgba(106, 168, 255, 0.22);
  background: var(--blue-soft);
  color: var(--blue);
}

.status-chip.error {
  border-color: rgba(255, 107, 122, 0.22);
  background: var(--red-soft);
  color: var(--red);
}

.status-rows {
  display: flex;
  flex-direction: column;
}

.status-rows > div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 7px 0;
  border-top: 1px solid var(--line);
}

.status-rows > div:first-child {
  padding-top: 0;
  border-top: 0;
}

.status-rows span {
  color: var(--muted-2);
  font-size: 0.68rem;
}

.status-rows strong {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.68rem;
  font-weight: 500;
  text-align: right;
}

.market-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.market-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 0;
  border-top: 1px solid var(--line);
}

.market-row:first-child {
  padding-top: 0;
  border-top: 0;
}

.market-row:last-child {
  padding-bottom: 0;
}

.market-id strong {
  display: block;
  font-size: 0.76rem;
}

.market-id span {
  display: block;
  color: var(--muted-2);
  font-size: 0.6rem;
}

.market-quote {
  text-align: right;
}

.market-quote strong {
  display: block;
  font-family: var(--mono);
  font-size: 0.7rem;
  font-weight: 500;
}

.market-quote span {
  display: block;
  font-family: var(--mono);
  font-size: 0.62rem;
}

.up {
  color: var(--green);
}

.down {
  color: var(--red);
}

.movers {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.mover-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border: 1px solid var(--line);
  border-radius: 7px;
  color: var(--muted-2);
  font-size: 0.6rem;
}

.mover-chip strong {
  color: var(--muted);
  font-family: var(--mono);
  font-weight: 500;
}

.btc-price {
  display: block;
  margin: 2px 0 12px;
  font-family: var(--mono);
  font-size: 1.5rem;
  font-weight: 500;
  letter-spacing: -0.04em;
}

.trend-badge {
  padding: 4px 8px;
  border-radius: 6px;
  background: rgba(148, 163, 184, 0.08);
  color: var(--muted);
  font-family: var(--mono);
  font-size: 0.58rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.trend-badge.up {
  background: var(--green-soft);
  color: var(--green);
}

.trend-badge.down {
  background: var(--red-soft);
  color: var(--red);
}

.btc-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.btc-metrics > div {
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(4, 8, 14, 0.35);
}

.btc-metrics span {
  display: block;
  color: var(--muted-2);
  font-size: 0.58rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.btc-metrics strong {
  display: block;
  margin-top: 2px;
  font-family: var(--mono);
  font-size: 0.68rem;
  font-weight: 500;
}

.rule-list {
  display: flex;
  flex-direction: column;
  gap: 13px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rule-list li {
  display: flex;
  gap: 10px;
}

.rule-dot {
  flex: none;
