function enterDesk() {
  loginView.hidden = true;
  appView.hidden = false;
  usernameInput.value = "Bombard";
  loadHistory();
  renderHistory();
  renderStats();
  renderStatus();
  startClock();
  scan();
}

loadHistory();
if (sessionStorage.getItem(SESSION_KEY) === "1") {
  enterDesk();
} else {
  usernameInput.value = "Bombard";
  usernameInput.focus();
  usernameInput.select();
}

