Announcement fetch:
```js
async function fetchAnnouncements() {
  if (Date.now() - state.announcementsAt < 4*60*1000 && state.announcements.length) return state.announcements;
  try {
    const data = await apiUrl("https://www.binance.com/bapi/composite/v1/public/cms/article/list/query?type=1&pageNo=1&pageSize=40");
    const catalogs = data?.data?.catalogs || [];
    const items = [];
    for (const catalog of catalogs) {
      const kind = catalogKind(catalog.catalogName);
      for (const article of catalog.articles || []) {
        items.push({
          id: `bn-${article.id}`,
          kind,
          catalog: catalog.catalogName,
          title: article.title,
          ts: Number(article.releaseDate) || 0,
          url: `https://www.binance.com/en/support/announcement/${article.code}`,
          source: "Binance",
        });
      }
    }
    state.announcements = items.sort((a,b)=>b.ts-a.ts);
    state.announcementsAt = Date.now();
  } catch { /* leave previous */ }
  return state.announcements;
}
```

