```js
function marketEventsFor(symbol, candles) {
  const now = Date.now();
  const events = [];
  const defs = [
    { key: "24h", ms: 864e5, label: "24 hours", scope: ["24h"] },
    { key: "4h", ms: 144e5, label: "4 hours", scope: ["24h","4h"] },
    { key: "1h", ms: 36e5, label: "hour", scope: ["24h","4h","1h"] },
  ];
  for (const def of defs) {
    const slice = candles.filter(c => c.closeTime > now - def.ms);
    if (slice.length < 2) continue;
    const first = slice[0], last = slice.at(-1);
    const change = (last.close / first.open - 1) * 100;
    const high = Math.max(...slice.map(c => c.high));
    const low = Math.min(...slice.map(c => c.low));
    const volume = slice.reduce((s,c)=>s+c.quoteVolume,0);
    const prior = candles.filter(c => c.closeTime <= now - def.ms && c.closeTime > now - 2*def.ms);
    const priorVolume = prior.reduce((s,c)=>s+c.quoteVolume,0);
    const volumeRatio = priorVolume > 0 ? volume / priorVolume : null;
    events.push({
      id: `mkt-${def.key}-move`, ts: last.closeTime, scope: def.scope,
      tag: `${change>=0?"+":""}${change.toFixed(2)}%`, cls: change>=0?"up":"down",
      title: `${symbol} is ${change>=0?"up":"down"} ${Math.abs(change).toFixed(2)}% over the last ${def.label}, trading at ${fmtPrice(last.close)}.`,
      source: "Market data",
    });
    if (volumeRatio && volumeRatio >= 1.25) {
      events.push({
        id: `mkt-${def.key}-vol`, ts: last.closeTime, scope: def.scope,
        tag: `${volumeRatio.toFixed(2)}× vol`, cls: "exchange",
        title: `Traded volume is ${volumeRatio.toFixed(2)}× the previous ${def.label} — ${fmtCompact(volume)} in quote volume.`,
        source: "Market data",
      });
    }
    const range = high - low;
    if (range > 0) {
      const pos = (last.close - low) / range;
      if (pos >= 0.85) events.push({ ... `Price sits near the top of its ${def.label} range (${fmtPrice(high)} high).` ... tag:"Near high", cls:"up" });
      else if (pos <= 0.15) events.push({ ... near low ... });
    }
  }
  // scanner signal
  const signal = state.signals.find(s=>s.symbol===symbol);
  if (signal) events.push({ id:`sig-${signal.candleTime}`, ts: signal.candleTime, scope:["24h","4h","1h"], tag:`${signal.score}/100`, cls:"listing", title:`Scanner flagged ${signal.side.toUpperCase()} · ${signal.setup} at ${fmtPrice(signal.entry)}.`, source:"Signal desk" });
  return events;
}
```

