function drawFallbackChart() {
  const host = $("tv-chart");
  const candles = state.chartKlines;
  if (!candles || candles.length < 2) {
    host.innerHTML = `<div class="chart-loading">TradingView could not load here. <a href="..." target="_blank" rel="noopener">Open the chart on TradingView ↗</a></div>`;
    return;
  }
  const closes = candles.map(c=>c.close);
  const min = Math.min(...closes), max = Math.max(...closes);
  const span = max - min || 1;
  const w = 600, h = 260, pad = 8;
  const points = closes.map((v,i)=>`${pad + (i/(closes.length-1))*(w-pad*2)},${pad + (1-(v-min)/span)*(h-pad*2)}`).join(" ");
  const up = closes.at(-1) >= closes[0];
  const color = up ? "#38e0a0" : "#ff6b7a";
  host.innerHTML = `<div class="chart-fallback">
    <svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-label="${state.selectedSymbol} 5 minute closes">
      <polyline points="${points}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/>
    </svg>
    <span>TradingView widget unavailable — showing Binance 5m closes. <a href="...">Open TradingView ↗</a></span>
  </div>`;
}
