```js
const STREAM_HOSTS = ["wss://stream.binance.com:9443/ws", "wss://data-stream.binance.vision/ws"];

function connectLive(symbol) {
  disconnectLive();
  state.socketSymbol = symbol;
  state.socketAttempt = 0;
  state.trades = [];
  state.livePrice = null;
  openSocket();
}

function openSocket() {
  const symbol = state.socketSymbol;
  if (!symbol) return;
  if (state.socketAttempt >= STREAM_HOSTS.length) { setFeedStatus("offline", "Polling"); return; }
  const host = STREAM_HOSTS[state.socketAttempt];
  let socket;
  try { socket = new WebSocket(`${host}/${symbol.toLowerCase()}@trade`); }
  catch { state.socketAttempt += 1; openSocket(); return; }
  state.socket = socket;
  setFeedStatus("connecting", "Connecting");
  const failTimer = setTimeout(() => {
    if (state.socket === socket && socket.readyState !== WebSocket.OPEN) {
      try { socket.close(); } catch {}
    }
  }, 6000);

  socket.addEventListener("open", () => {
    clearTimeout(failTimer);
    if (state.socket !== socket) return;
    setFeedStatus("live", "Live");
    state.socketAttempt = 0;
  });
  socket.addEventListener("message", (event) => {
    if (state.socket !== socket) return;
    try {
      const data = JSON.parse(event.data);
      if (data.e === "trade") handleTrade(data);
    } catch {}
  });
  socket.addEventListener("close", () => {
    clearTimeout(failTimer);
    if (state.socket !== socket) return;
    state.socket = null;
    if (state.socketSymbol !== symbol) return;
    state.socketAttempt += 1;
    if (state.socketAttempt < STREAM_HOSTS.length) {
      setFeedStatus("connecting", "Reconnecting");
      setTimeout(() => { if (state.socketSymbol === symbol && !state.socket) openSocket(); }, 800);
    } else {
      setFeedStatus("offline", "Polling");
    }
  });
  socket.addEventListener("error", () => { try { socket.close(); } catch {} });
}
```

