async function loadAnnouncements() {
  if (state.announcements.length && Date.now() - state.announcementsAt < 5 * 60 * 1000) {
    return state.announcements;
  }
  try {
    const payload = await fetchJson("https://www.binance.com/bapi/composite/v1/public/cms/article/list/query?type=1&pageNo=1&pageSize=40");
    const catalogs = payload?.data?.catalogs || [];
    const items = [];
    for (const catalog of catalogs) {
      const kind = catalogKind(catalog.catalogName);
      for (const article of catalog.articles || []) {
        if (!article?.title || !article?.code) continue;
        items.push({
          id: `bn-${article.id}`,
          kind,
          title: article.title,
          ts: Number(article.releaseDate) || 0,
          url: `https://www.binance.com/en/support/announcement/${article.code}`,
        });
      }
    }
    state.announcements = items.filter(a => a.ts > 0).sort((a,b)=>b.ts-a.ts);
    state.announcementsAt = Date.now();
  } catch {
    /* keep whatever we had; market events still populate the feed */
  }
  return state.announcements;
}
