```js
export function backtest(candles, config = CONFIG, options = {}) {
  const maxHold = options.maxHold ?? 48; // 48 × 5m = 4h
  const warmup = options.warmup ?? 60;
  const trades = [];
  if (!candles || candles.length < warmup + maxHold + 2) {
    return { trades, wins: 0, losses: 0, timeouts: 0, accuracy: 0, ... };
  }

  for (let index = warmup; index < candles.length - 1; index += 1) {
    const window = candles.slice(0, index + 1);
    const signal = evaluateSymbol(window, config);
    if (!signal) continue;

    const entryCandle = candles[index + 1];
    const entry = entryCandle.open;
    if (!Number.isFinite(entry) || entry <= 0) continue;

    const risk = Math.abs(signal.entry - signal.stop);
    if (!(risk > 0)) continue;
    const reward = Math.abs(signal.takeProfit1 - signal.entry);
    const isLong = signal.side === "long";
    const stop = isLong ? entry - risk : entry + risk;
    const target = isLong ? entry + reward : entry - reward;
    if (target <= 0) continue;

    let outcome = "timeout";
    let exitPrice = candles[Math.min(index + maxHold, candles.length - 1)].close;
    for (let j = index + 1; j < Math.min(index + 1 + maxHold, candles.length); j += 1) {
      const candle = candles[j];
      const hitStop = isLong ? candle.low <= stop : candle.high >= stop;
      const hitTarget = isLong ? candle.high >= target : candle.low <= target;
      if (hitStop && hitTarget) { outcome = "loss"; exitPrice = stop; break; }
      if (hitStop) { outcome = "loss"; exitPrice = stop; break; }
      if (hitTarget) { outcome = "win"; exitPrice = target; break; }
    }
    const rMultiple = isLong ? (exitPrice - entry) / risk : (entry - exitPrice) / risk;
    trades.push({
      candleTime: signal.candleTime,
      side: signal.side,
      setup: signal.setup,
      score: signal.score,
      entry, stop, target,
      exitPrice,
      outcome,
      r: Number(rMultiple.toFixed(3)),
    });
  }

  const wins = trades.filter(t => t.outcome === "win").length;
  const losses = trades.filter(t => t.outcome === "loss").length;
  const timeouts = trades.filter(t => t.outcome === "timeout").length;
  const decided = wins + losses + timeouts;
  const accuracy = decided ? (wins / decided) * 100 : 0;
  const totalR = trades.reduce((sum, t) => sum + t.r, 0);
  const grossWin = trades.filter(t => t.r > 0).reduce((s,t)=>s+t.r,0);
  const grossLoss = Math.abs(trades.filter(t => t.r < 0).reduce((s,t)=>s+t.r,0));
  const profitFactor = grossLoss > 0 ? grossWin / grossLoss : grossWin > 0 ? Infinity : 0;
  // equity curve & max drawdown
  let equity = 0, peak = 0, maxDrawdown = 0;
  const curve = [];
  for (const trade of trades) {
    equity += trade.r;
    peak = Math.max(peak, equity);
    maxDrawdown = Math.max(maxDrawdown, peak - equity);
    curve.push(Number(equity.toFixed(3)));
  }
  const avgR = trades.length ? totalR / trades.length : 0;
  return { trades, wins, losses, timeouts, decided, accuracy, totalR, avgR, profitFactor, maxDrawdown, curve };
}
```

