/* ---------- Backtest ---------- */

.backtest-panel {
  margin-bottom: 18px;
  padding: 18px;
}

.backtest-panel .panel-head {
  margin-bottom: 12px;
}

.backtest-panel .panel-head h3 {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 9px;
  font-size: 1.1rem;
}

.backtest-body {
  display: grid;
  grid-template-columns: 142px minmax(0, 1fr);
  gap: 24px;
  align-items: center;
}

.backtest-gauge {
  position: relative;
  width: 132px;
  height: 132px;
}

.backtest-gauge svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.backtest-gauge circle {
  fill: none;
  stroke-width: 8;
}

.backtest-track {
  stroke: rgba(148, 163, 184, 0.12);
}

.backtest-value {
  stroke: var(--green);
  stroke-linecap: round;
  filter: drop-shadow(0 0 7px rgba(56, 224, 160, 0.32));
  transition: stroke-dashoffset 0.8s ease, stroke 0.3s ease;
}

.backtest-value.warn {
  stroke: var(--amber);
}

.backtest-value.bad {
  stroke: var(--red);
}

.backtest-score {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: baseline;
  justify-content: center;
  padding-top: 47px;
}

.backtest-score strong {
  font-size: 2rem;
  letter-spacing: -0.05em;
}

.backtest-score span {
  color: var(--muted-2);
  font-size: 0.6rem;
}

.backtest-verdict {
  margin: 0 0 12px;
  color: var(--text);
  font-size: 0.84rem;
}

.backtest-verdict strong {
  color: var(--green);
}

.backtest-stats {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 8px;
}

.backtest-stat {
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(4, 8, 14, 0.4);
}

.backtest-stat span {
  display: block;
  color: var(--muted-2);
  font-size: 0.52rem;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.backtest-stat strong {
  display: block;
  margin-top: 2px;
  font-family: var(--mono);
  font-size: 0.76rem;
  font-weight: 500;
}

.backtest-note {
  margin: 12px 0 0;
  color: var(--muted-2);
  font-size: 0.58rem;
  line-height: 1.5;
}

/* ---------- Pair news ---------- */

