Wait, I inserted the responsive block in the 820 media query? The oldString `.backtest-body { grid-template-columns: 1fr; justify-items: start; }` appears in the 820 media query I added earlier. Good. But `.ticket-grid` base is defined; the responsive override goes there. Fine.

Now app.js: add state for account/risk, ticket render, timing countdown update, events, boot.

Add state fields:
```js
accountSize: 1000,
riskPct: 1,
```
Load from localStorage at boot.

renderTicket function. Add after renderBacktest or before Events. Also `ticketText()` for copy.

Implementation:

```js
function loadTicketSettings() {
  try {
    const account = Number(localStorage.getItem("signalDesk.account"));
    const risk = Number(localStorage.getItem("signalDesk.risk"));
    if (Number.isFinite(account) && account >= 10) state.accountSize = account;
    if (Number.isFinite(risk) && risk > 0 && risk <= 10) state.riskPct = risk;
  } catch {}
  $("calc-account").value = String(state.accountSize);
  $("calc-risk").value = String(state.riskPct);
}

function saveTicketSettings() { try { ... } catch {} }

function renderTicket() {
  const panel = $("ticket-panel");
  const symbol = state.selectedSymbol;
  const signal = state.signals.find(s => s.symbol === symbol) || null;
  const snapshot = indicatorSnapshot(state.chartKlines, CONFIG);
  const side = $("ticket-side");
  const score = $("ticket-score");

  $("ticket-symbol").textContent = symbol;
  panel.classList.toggle("no-trade", !signal);

  if (signal) {
    side.hidden = false;
    side.className = `side-pill ${signal.side}`;
    side.textContent = signal.side.toUpperCase();
    score.textContent = `Score ${signal.score}/100`;
    $("ticket-setup").textContent = signal.setup;
  } else {
    side.hidden = true;
    score.textContent = snapshot ? "No trigger" : "Waiting";
    $("ticket-setup").textContent = snapshot
      ? "No qualifying setup on this pair right now. The checklist shows what is missing."
      : "Reading the latest closed candles…";
  }

  renderTicketLevels(signal, snapshot);
  renderTicketTiming(signal, snapshot);
  renderTicketChecklist(signal, snapshot);
  renderTicketCalc(signal, snapshot);
  updateTicketCountdown();
}
```

Levels:
```js
function renderTicketLevels(signal, snapshot) {
  const host = $("ticket-levels");
  if (!signal) {
    host.innerHTML = `
      ${levelCard("Price", snapshot ? fmtPrice(snapshot.price) : "—", "Last closed 5m", "")}
      ${levelCard("Support", snapshot ? fmtPrice(snapshot.support) : "—", "48-candle low", "")}
      ${levelCard("Resistance", snapshot ? fmtPrice(snapshot.resistance) : "—", "48-candle high", "")}
      ${levelCard("ATR 14", snapshot ? `${snapshot.atrPct.toFixed(2)}%` : "—", "Volatility", "")}
    `;
    return;
  }
  const risk = Math.abs(signal.entry - signal.stop);
  const tp1R = risk > 0 ? Math.abs(signal.takeProfit1 - signal.entry) / risk : 0;
  const tp2R = risk > 0 ? Math.abs(signal.takeProfit2 - signal.entry) / risk : 0;
  host.innerHTML = `
    ${levelCard("Entry", fmtPrice(signal.entry), "Signal close", "entry")}
    ${levelCard("Stop", fmtPrice(signal.stop), `${((risk / signal.entry) * 100).toFixed(2)}% risk`, "stop")}
    ${levelCard("Target 1", fmtPrice(signal.takeProfit1), `${tp1R.toFixed(1)}R`, "tp")}
    ${levelCard("Target 2", fmtPrice(signal.takeProfit2), `${tp2R.toFixed(1)}R`, "tp")}
  `;
}
function levelCard(label, value, sub, cls) {
  return `<div class="ticket-level ${cls}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`;
}
```

Timing:
```js
function renderTicketTiming(signal, snapshot) {
  const timeframe = $("ticket-timeframe");
  const trigger = $("ticket-trigger");
  if (!signal) {
    timeframe.textContent = "Wait for a 5m close";
    trigger.textContent = snapshot
      ? `No entry yet. Watch the next 5m close: it must clear resistance at ${fmtPrice(snapshot.resistance)} or reject support at ${fmtPrice(snapshot.support)}.`
      : "Waiting for closed candles to evaluate the trigger.";
    return;
  }
  timeframe.textContent = "5-minute close";
  if (signal.setup === "Resistance breakout") {
    trigger.textContent = `Confirmed on the 5m close above ${fmtPrice(signal.resistance)}. Aggressive: next candle open. Conservative: wait for a 1m retest that holds ${fmtPrice(signal.resistance)}.`;
  } else if (signal.setup === "Support rejection") {
    trigger.textContent = `Confirmed on the 5m bullish rejection close above ${fmtPrice(signal.support)}. Conservative: wait for a 1m higher low above ${fmtPrice(signal.support)}.`;
  } else {
    trigger.textContent = "Confirmed on the closed 5m signal candle. Use the 1m chart only to refine the fill.";
  }
}
```

Countdown:
```js
function updateTicketCountdown() {
  const node = $("ticket-countdown");
  if (!node) return;
  const now = Date.now();
  const boundary = nextBoundary(new Date(now)).getTime();
  const remaining = Math.max(0, boundary - now);
  const minutes = Math.floor(remaining / 60000);
  const seconds = Math.floor((remaining % 60000) / 1000);
  node.textContent = `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}
```
Call in tick().

Checklist:
```js
function renderTicketChecklist(signal, snapshot) {
  const host = $("ticket-checklist");
  if (!snapshot) { host.innerHTML = `<li><span class="check-icon fail">…</span>Waiting for candle data.</li>`; return; }
  const structurePass = signal ? true : (snapshot.price > snapshot.resistance || (snapshot.candleLow <= snapshot.support + 0.35 * snapshot.atr && snapshot.candleClose > snapshot.support && snapshot.candleClose > snapshot.candleOpen));
  const checks = [
    ["EMA 20 above EMA 50", snapshot.trend === "up"],
    [`Volume ≥ ${snapshot.minVolumeRatio.toFixed(1)}× average`, snapshot.volumeRatio != null && snapshot.volumeRatio >= snapshot.minVolumeRatio],
    ["RSI inside the 50–72 band", snapshot.rsi >= 50 && snapshot.rsi <= 72],
    [`ATR inside ${snapshot.minAtrPct.toFixed(2)}–${snapshot.maxAtrPct.toFixed(2)}%`, snapshot.atrPct >= snapshot.minAtrPct && snapshot.atrPct <= snapshot.maxAtrPct],
    ["Structure trigger confirmed", structurePass],
    [`Confluence score ≥ ${snapshot.minScore}`, Boolean(signal)],
  ];
  host.innerHTML = checks.map(([label, pass]) => `<li><span class="check-icon ${pass ? "pass" : "fail"}">${pass ? "✓" : "✕"}</span><span>${label}</span></li>`).join("");
}
```

Calc:
```js
function renderTicketCalc(signal, snapshot) {
  const out = $("calc-out");
  const account = state.accountSize;
  const riskPct = state.riskPct;
  const riskAmount = (account * riskPct) / 100;
  if (!signal) {
    out.innerHTML = `
      <div><span>Risk budget</span><strong>${fmtMoney(riskAmount)}</strong></div>
      <div><span>Plan</span><strong>No trade</strong></div>`;
    return;
  }
  const stopDistance = Math.abs(signal.entry - signal.stop);
  const units = stopDistance > 0 ? riskAmount / stopDistance : 0;
  const notional = units * signal.entry;
  const tp1Profit = units * Math.abs(signal.takeProfit1 - signal.entry);
  const tp2Profit = units * Math.abs(signal.takeProfit2 - signal.entry);
  out.innerHTML = `
    <div><span>Risk budget</span><strong>${fmtMoney(riskAmount)}</strong></div>
    <div><span>Position size</span><strong>${fmtQty(units)} ${signal.symbol.replace("USDT","")}</strong></div>
    <div><span>Notional</span><strong>${fmtMoney(notional)}</strong></div>
    <div><span>Max loss</span><strong>-${fmtMoney(riskAmount)}</strong></div>
    <div><span>TP1 profit</span><strong class="up">+${fmtMoney(tp1Profit)}</strong></div>
    <div><span>TP2 profit</span><strong class="up">+${fmtMoney(tp2Profit)}</strong></div>`;
}
function fmtMoney(value) {
  if (!Number.isFinite(value)) return "—";
  if (value >= 1000) return `$${value.toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
  return `$${value.toFixed(2)}`;
}
```

`fmtQty` for units: for BTC units ~0.01, fmtQty gives 0.01000? fmtQty: >=1 toFixed(3), else toFixed(5). 0.01 → "0.01000". Acceptable but trailing zeros. Could improve fmtQty to trim. Let me adjust fmtQty: `return value.toFixed(5).replace(/0+$/, "").replace(/\.$/, "")` but for 0.00001 it gives "0.00001". Fine. However for quantities like 1234.5, toLocaleString. Good.

Actually current fmtQty:
```js
if (value >= 1000) return value.toLocaleString(... max 1);
if (value >= 1) return value.toFixed(3);
return value.toFixed(5);
```
0.01000. Let me trim trailing zeros for <1:
```js
return value.toFixed(6).replace(/0+$/, "").replace(/\.$/, "");
```
Do it.

Copy plan:
```js
function ticketPlanText() {
  const signal = state.signals.find(s => s.symbol === state.selectedSymbol);
  if (!signal) return null;
  const account = state.accountSize;
  const riskAmount = (account * state.riskPct) / 100;
  const stopDistance = Math.abs(signal.entry - signal.stop);
  const units = stopDistance > 0 ? riskAmount / stopDistance : 0;
  return [
    `${signal.symbol} · ${signal.side.toUpperCase()} · ${signal.setup}`,
    `Suggested entry timeframe: 5m close`,
