    const host = $("tv-chart");
    if (host.querySelector("iframe")) return;
    drawFallbackChart();
  }, 9000);
}

function drawFallbackChart() {
  const host = $("tv-chart");
  const candles = state.chartKlines;
  const link = `https://www.tradingview.com/chart/?symbol=${encodeURIComponent(
    `BINANCE:${state.selectedSymbol}`,
  )}`;
  if (!candles || candles.length < 2) {
    host.innerHTML = `<div class="chart-loading">TradingView could not load in this browser. <a href="${link}" target="_blank" rel="noopener">Open the live chart on TradingView ↗</a></div>`;
    return;
  }

  const closes = candles.map((candle) => candle.close);
  const min = Math.min(...closes);
  const max = Math.max(...closes);
  const span = max - min || 1;
  const width = 600;
  const height = 260;
  const pad = 10;
  const points = closes
    .map((value, index) => {
      const x = pad + (index / (closes.length - 1)) * (width - pad * 2);
      const y = pad + (1 - (value - min) / span) * (height - pad * 2);
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .join(" ");
  const rising = closes.at(-1) >= closes[0];
  const stroke = rising ? "#38e0a0" : "#ff6b7a";

  host.innerHTML = `
    <div class="chart-fallback">
      <svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" aria-label="${escapeHtml(
        state.selectedSymbol,
      )} 5 minute closes">
        <polyline points="${points}" fill="none" stroke="${stroke}" stroke-width="2" vector-effect="non-scaling-stroke"></polyline>
      </svg>
      <span>TradingView widget unavailable — showing Binance 5m closes. <a href="${link}" target="_blank" rel="noopener">Open TradingView ↗</a></span>
    </div>`;
}

